        cin >> start >> end;
        goddess.push_back({start, end});
    }

    int M;
    cin >> M;

    // Read programmer intervals
    vector<pair<int, int>> programmers;
    for (int i = 0; i < M; i++) {
        int start, end;
        cin >> start >> end;
        programmers.push_back({start, end});
    }

    // Sort goddess intervals
    sort(goddess.begin(), goddess.end());

    // Merge goddess intervals
    vector<pair<int, int>> mergedGoddess;
    for (auto &interval : goddess) {
        if (mergedGoddess.empty() || interval.first > mergedGoddess.back().second) {
            mergedGoddess.push_back(interval);
        } else {
            mergedGoddess.back().second = max(mergedGoddess.back().second, interval.second);
        }
    }

    long long maxBlessed = 0;

    // For each programmer, compute blessed time
    for (auto &prog : programmers) {
        long long blessed = 0;
        int pStart = prog.first, pEnd = prog.second;

        // Binary search to find first goddess interval that might overlap
        int left = 0, right = (int)mergedGoddess.size() - 1;
        int idx = -1;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (mergedGoddess[mid].second >= pStart) {
                idx = mid;
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }

        if (idx == -1) continue; // no overlap

        // Iterate through overlapping goddess intervals
        for (int i = idx; i < (int)mergedGoddess.size(); i++) {
            int gStart = mergedGoddess[i].first;
            int gEnd = mergedGoddess[i].second;

            if (gStart > pEnd) break; // no more overlap

            int overlapStart = max(pStart, gStart);
            int overlapEnd = min(pEnd, gEnd);
            if (overlapStart < overlapEnd) {
                blessed += (overlapEnd - overlapStart);
            }
        }

        maxBlessed = max(maxBlessed, blessed);
    }

    cout << maxBlessed << "\n";

    return 0;
}

