};

int parseTime(const string& s) {
    // format: hh:mm
    int h = stoi(s.substr(0, 2));
    int m = stoi(s.substr(3, 2));
    return h * 60 + m;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    vector<Event> events;
    for (int i = 0; i < n; ++i) {
        string t, who, action;
        cin >> t >> who >> action;
        int tm = parseTime(t);

        int delta = (action == "enters" || action == "arrives") ? 1 : -1;

        if (who == "goddess") {
            events.push_back({tm, 0, "", delta});
        } else {
            events.push_back({tm, 1, who, delta});
        }
    }

    sort(events.begin(), events.end(), [](const Event& a, const Event& b) {
        if (a.time != b.time) return a.time < b.time;
        // Process all events at same time together anyway; order here not important.
        return a.type < b.type;
    });

    unordered_map<string, int> present;
    unordered_map<string, long long> blessed;

    bool goddessPresent = false;
    int prevTime = events.empty() ? 0 : events[0].time;

    int i = 0;
    while (i < (int)events.size()) {
        int curTime = events[i].time;

        if (goddessPresent) {
            int dt = curTime - prevTime;
            if (dt > 0) {
                for (auto &p : present) {
                    if (p.second > 0) blessed[p.first] += dt;
                }
            }
        }

        while (i < (int)events.size() && events[i].time == curTime) {
            if (events[i].type == 0) {
                goddessPresent = (events[i].delta == 1);
            } else {
                present[events[i].name] += events[i].delta;
            }
            ++i;
        }

        prevTime = curTime;
    }

    long long ans = 0;
    for (auto &p : blessed) ans = max(ans, p.second);

    cout << ans << '\n';
    return 0;
}

