#define MAX_EVENTS 200000

typedef struct {
    long long time;
    int type; // 1 = goddess arrival, 2 = goddess departure, 3 = programmer arrival, 4 = programmer departure
    int id;   // programmer id (0 for goddess)
} Event;

int cmp(const void *a, const void *b) {
    Event *ea = (Event *)a;
    Event *eb = (Event *)b;
    if (ea->time != eb->time)
        return (ea->time > eb->time) ? 1 : -1;
    // Process departures before arrivals at same time to avoid counting zero intervals
    return ea->type - eb->type;
}

int main() {
    int n;
    scanf("%d", &n);

    Event events[MAX_EVENTS];
    int event_count = 0;

    // Read goddess events
    for (int i = 0; i < n; i++) {
        char type[10];
        long long h, m;
        scanf("%s %lld:%lld", type, &h, &m);
        long long minutes = h * 60 + m;
        if (strcmp(type, "GODDESS") == 0) {
            events[event_count].time = minutes;
            events[event_count].type = 1; // arrival
            events[event_count].id = 0;
            event_count++;
        } else if (strcmp(type, "DEVIL") == 0) {
            events[event_count].time = minutes;
            events[event_count].type = 2; // departure
            events[event_count].id = 0;
            event_count++;
        }
    }

    // Read programmer events
    int m;
    scanf("%d", &m);
    for (int i = 0; i < m; i++) {
        int id;
        char action[10];
        long long h, m_time;
        scanf("%d %s %lld:%lld", &id, action, &h, &m_time);
        long long minutes = h * 60 + m_time;
        if (strcmp(action, "ARRIVES") == 0) {
            events[event_count].time = minutes;
            events[event_count].type = 3;
            events[event_count].id = id;
            event_count++;
        } else if (strcmp(action, "DEPARTS") == 0) {
            events[event_count].time = minutes;
            events[event_count].type = 4;
            events[event_count].id = id;
            event_count++;
        }
    }

    // Sort events by time
    qsort(events, event_count, sizeof(Event), cmp);

    // Track goddess presence
    int goddess_present = 0;
    long long goddess_start = 0;

    // Track programmer presence and blessed time
    // We'll use a simple array since programmer IDs are up to 1000
    long long blessed_time[1001] = {0};
    int programmer_present[1001] = {0};
    long long programmer_start[1001] = {0};

    // Process events
    for (int i = 0; i < event_count; i++) {
        Event e = events[i];

        if (e.type == 1) { // Goddess arrival
            if (!goddess_present) {
                goddess_present = 1;
                goddess_start = e.time;
            }
        } else if (e.type == 2) { // Goddess departure
            if (goddess_present) {
                // For all programmers currently present, add blessed time
                for (int id = 1; id <= 1000; id++) {
                    if (programmer_present[id]) {
                        blessed_time[id] += e.time - (programmer_start[id] > goddess_start ? programmer_start[id] : goddess_start);
                        programmer_start[id] = e.time; // update start for next goddess interval
                    }
                }
                goddess_present = 0;
            }
        } else if (e.type == 3) { // Programmer arrival
            if (!programmer_present[e.id]) {
                programmer_present[e.id] = 1;
                programmer_start[e.id] = e.time;
            }
        } else if (e.type == 4) { // Programmer departure
            if (programmer_present[e.id]) {
                if (goddess_present) {
                    long long start = programmer_start[e.id] > goddess_start ? programmer_start[e.id] : goddess_start;
                    if (start < e.time) {
                        blessed_time[e.id] += e.time - start;
                    }
                }
                programmer_present[e.id] = 0;
            }
        }
    }

    // Find programmer with maximum blessed time
    long long max_time = -1;
    int max_id = -1;
    for (int id = 1; id <= 1000; id++) {
        if (blessed_time[id] > max_time) {
            max_time = blessed_time[id];
            max_id = id;
        }
    }

    printf("%d %lld\n", max_id, max_time);

    return 0;
}

