#define MAXN 200000
#define NAME_LEN 64

typedef struct {
    int time;
    int type;   // 0 = goddess, 1 = programmer
    int id;     // programmer id, ignored for goddess
    int delta;  // +1 enter, -1 leave
} Event;

typedef struct {
    char name[NAME_LEN];
    long long blessed;
} Person;

static Event events[MAXN];
static Person people[MAXN];
static int peopleCount = 0;

int get_id(const char *name) {
    for (int i = 0; i < peopleCount; i++) {
        if (strcmp(people[i].name, name) == 0) return i;
    }
    strcpy(people[peopleCount].name, name);
    people[peopleCount].blessed = 0;
    return peopleCount++;
}

int cmp_event(const void *a, const void *b) {
    const Event *x = (const Event *)a;
    const Event *y = (const Event *)b;
    if (x->time != y->time) return x->time - y->time;

    /* Process leaves before enters at the same time */
    int px = (x->delta == -1 ? 0 : 1);
    int py = (y->delta == -1 ? 0 : 1);
    if (px != py) return px - py;

    /* Tie-breaker irrelevant, keep deterministic */
    if (x->type != y->type) return x->type - y->type;
    return x->id - y->id;
}

int parse_time(const char *s) {
    int h, m;
    sscanf(s, "%d:%d", &h, &m);
    return h * 60 + m;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int ecnt = 0;

    for (int i = 0; i < n; i++) {
        char who[NAME_LEN], action[16], ts[16];
        scanf("%s %s %s", who, action, ts);

        int t = parse_time(ts);
        int delta = 0;

        if (strcmp(action, "arrives") == 0 || strcmp(action, "enters") == 0)
            delta = +1;
        else
            delta = -1;

        if (strcmp(who, "Goddess") == 0 || strcmp(who, "goddess") == 0) {
            events[ecnt++] = (Event){t, 0, -1, delta};
        } else {
            int id = get_id(who);
            events[ecnt++] = (Event){t, 1, id, delta};
        }
    }

    qsort(events, ecnt, sizeof(Event), cmp_event);

    int goddessInside = 0;
    char *inside = (char *)calloc(peopleCount ? peopleCount : 1, sizeof(char));
    int activeProgrammers = 0;
    long long currentBlessedStart = -1;

    int i = 0;
    while (i < ecnt) {
        int currentTime = events[i].time;

        if (currentBlessedStart != -1) {
            long long dt = currentTime - currentBlessedStart;
            if (dt > 0) {
                for (int k = 0; k < peopleCount; k++) {
                    if (inside[k]) people[k].blessed += dt;
                }
            }
            currentBlessedStart = -1;
        }

        while (i < ecnt && events[i].time == currentTime) {
            Event e = events[i];
            if (e.type == 0) {
                goddessInside += e.delta;
            } else {
                if (e.delta == +1) {
                    if (!inside[e.id]) {
                        inside[e.id] = 1;
                        activeProgrammers++;
                    }
                } else {
                    if (inside[e.id]) {
                        inside[e.id] = 0;
                        activeProgrammers--;
                    }
                }
            }
            i++;
        }

        if (goddessInside > 0 && activeProgrammers > 0) {
            currentBlessedStart = currentTime;
        }
    }

    long long ans = 0;
    for (int k = 0; k < peopleCount; k++) {
        if (people[k].blessed > ans) ans = people[k].blessed;
    }

    printf("%lld\n", ans);

    free(inside);
    return 0;
}

