import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        // Read number of entries
        int n = Integer.parseInt(br.readLine());

        // Store events: (time, type, programmerId)
        // type: 0 = goddess arrival, 1 = goddess departure
        //       2 = programmer arrival, 3 = programmer departure
        List<Event> events = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            String[] parts = br.readLine().split(" ");
            String type = parts[0];
            int id = Integer.parseInt(parts[1]);
            int time = Integer.parseInt(parts[2]);

            if (type.equals("GOD")) {
                if (id == 1) { // arrival
                    events.add(new Event(time, 0, -1));
                } else { // departure
                    events.add(new Event(time, 1, -1));
                }
            } else if (type.equals("PROG")) {
                if (id >= 0) { // arrival
                    events.add(new Event(time, 2, id));
                } else { // departure
                    events.add(new Event(time, 3, -id));
                }
            }
        }

        // Sort events by time
        Collections.sort(events, (a, b) -> a.time - b.time);

        // Track state
        boolean goddessPresent = false;
        int goddessStart = 0;
        Map<Integer, Integer> progArrival = new HashMap<>(); // programmerId -> arrival time
        Map<Integer, Integer> blessedTime = new HashMap<>(); // programmerId -> total blessed time

        for (Event e : events) {
            if (e.type == 0) { // goddess arrival
                goddessPresent = true;
                goddessStart = e.time;
                // Check which programmers are currently present
                for (Map.Entry<Integer, Integer> entry : progArrival.entrySet()) {
                    int progId = entry.getKey();
                    int arrivalTime = entry.getValue();
                    // This programmer is present when goddess arrives
                    // Start counting from goddess arrival
                    // We'll handle this by keeping track that this programmer started being blessed
                    // We'll mark arrival time as goddessStart for blessed calculation
                    // Actually we need to update the arrival time to goddessStart for this programmer
                    // because blessed time starts from goddess arrival
                    // But careful: if programmer arrived before goddess, blessed time starts from goddess arrival
                    // We'll store the blessed start time separately
                    // We'll use a map to store when blessed counting started for each programmer
                }
            } else if (e.type == 1) { // goddess departure
                goddessPresent = false;
                // Add blessed time for all programmers present
                for (Map.Entry<Integer, Integer> entry : progArrival.entrySet()) {
                    int progId = entry.getKey();
                    int arrivalTime = entry.getValue();
                    int blessedStart = Math.max(arrivalTime, goddessStart);
                    int blessed = e.time - blessedStart;
                    if (blessed > 0) {
                        blessedTime.put(progId, blessedTime.getOrDefault(progId, 0) + blessed);
                    }
                }
                // Reset programmer arrivals? No, they remain present but not blessed
            } else if (e.type == 2) { // programmer arrival
                progArrival.put(e.id, e.time);
                // If goddess is present, start counting blessed time from now
                // But we'll handle it in departure or goddess departure
            } else if (e.type == 3) { // programmer departure
                int progId = e.id;
                if (progArrival.containsKey(progId)) {
                    int arrivalTime = progArrival.get(progId);
                    if (goddessPresent) {
                        int blessedStart = Math.max(arrivalTime, goddessStart);
                        int blessed = e.time - blessedStart;
                        if (blessed > 0) {
                            blessedTime.put(progId, blessedTime.getOrDefault(progId, 0) + blessed);
                        }
                    }
                    progArrival.remove(progId);
                }
            }
        }

        // Find programmer with max blessed time
        int maxTime = 0;
        int maxId = -1;
        for (Map.Entry<Integer, Integer> entry : blessedTime.entrySet()) {
            if (entry.getValue() > maxTime) {
                maxTime = entry.getValue();
                maxId = entry.getKey();
            }
        }

        System.out.println(maxTime);
    }

    static class Event {
        int time;
        int type; // 0: goddess arrival, 1: goddess departure, 2: prog arrival, 3: prog departure
        int id; // programmer id (positive) or -1 for goddess

        Event(int time, int type, int id) {
            this.time = time;
            this.type = type;
            this.id = id;
        }
    }
}

