public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        List<int[]> goddessIntervals = new ArrayList<>();
        Map<String, List<int[]>> programmerIntervals = new HashMap<>();

        while (sc.hasNextLine()) {
            String line = sc.nextLine().trim();
            if (line.isEmpty()) continue;

            String[] parts = line.split("\\s+");
            if (parts.length < 3) continue;

            String name = parts[0];
            String arrivalStr = parts[1];
            String departureStr = parts[2];

            int arrival = parseTime(arrivalStr);
            int departure = parseTime(departureStr);

            if (name.equalsIgnoreCase("goddess")) {
                goddessIntervals.add(new int[]{arrival, departure});
            } else {
                programmerIntervals.computeIfAbsent(name, k -> new ArrayList<>())
                    .add(new int[]{arrival, departure});
            }
        }

        // For each programmer, compute total blessed time
        Map<String, Integer> blessedTime = new HashMap<>();

        for (Map.Entry<String, List<int[]>> entry : programmerIntervals.entrySet()) {
            String name = entry.getKey();
            List<int[]> pIntervals = entry.getValue();
            int total = 0;

            for (int[] pInterval : pIntervals) {
                for (int[] gInterval : goddessIntervals) {
                    int overlapStart = Math.max(pInterval[0], gInterval[0]);
                    int overlapEnd = Math.min(pInterval[1], gInterval[1]);
                    if (overlapEnd > overlapStart) {
                        total += overlapEnd - overlapStart;
                    }
                }
            }

            blessedTime.put(name, total);
        }

        // Find programmer with maximum blessed time
        int maxTime = -1;
        String winner = null;

        for (Map.Entry<String, Integer> entry : blessedTime.entrySet()) {
            if (entry.getValue() > maxTime) {
                maxTime = entry.getValue();
                winner = entry.getKey();
            }
        }

        if (winner != null) {
            System.out.println(maxTime);
        } else {
            System.out.println(0);
        }
    }

    static int parseTime(String time) {
        String[] parts = time.split(":");
        int hours = Integer.parseInt(parts[0]);
        int minutes = Integer.parseInt(parts[1]);
        return hours * 60 + minutes;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class Event {
        int time;
        int type; // 0 = goddess, 1 = programmer
        String name;
        boolean enter; // true = enters, false = leaves

        Event(int time, int type, String name, boolean enter) {
            this.time = time;
            this.type = type;
            this.name = name;
            this.enter = enter;
        }
    }

    static int parseTime(String s) {
        String[] parts = s.split(":");
        int h = Integer.parseInt(parts[0]);
        int m = Integer.parseInt(parts[1]);
        return h * 60 + m;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String first = br.readLine();
        if (first == null || first.trim().isEmpty()) {
            return;
        }

        int n = Integer.parseInt(first.trim());
        List<Event> events = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            String line = br.readLine();
            while (line != null && line.trim().isEmpty()) line = br.readLine();
            if (line == null) break;

            StringTokenizer st = new StringTokenizer(line);
            String timeStr = st.nextToken();
            String who = st.nextToken();
            String action = st.nextToken();

            int time = parseTime(timeStr);

            if (who.equals("Goddess")) {
                events.add(new Event(time, 0, "Goddess", action.equals("enters")));
            } else {
                events.add(new Event(time, 1, who, action.equals("enters")));
            }
        }

        events.sort((a, b) -> {
            if (a.time != b.time) return Integer.compare(a.time, b.time);
            if (a.enter != b.enter) return a.enter ? -1 : 1; // enters before leaves at same time
            if (a.type != b.type) return Integer.compare(a.type, b.type); // goddess before programmer
            return a.name.compareTo(b.name);
        });

        boolean goddessInside = false;
        Set<String> inside = new HashSet<>();
        Map<String, Integer> blessed = new HashMap<>();

        int prevTime = events.isEmpty() ? 0 : events.get(0).time;
        int i = 0;

        while (i < events.size()) {
            int currentTime = events.get(i).time;
            int delta = currentTime - prevTime;

            if (delta > 0 && goddessInside) {
                for (String name : inside) {
                    blessed.put(name, blessed.getOrDefault(name, 0) + delta);
                }
            }

            while (i < events.size() && events.get(i).time == currentTime) {
                Event e = events.get(i);
                if (e.type == 0) {
                    goddessInside = e.enter;
                } else {
                    if (e.enter) inside.add(e.name);
                    else inside.remove(e.name);
                }
                i++;
            }

            prevTime = currentTime;
        }

        int ans = 0;
        for (int v : blessed.values()) ans = Math.max(ans, v);
        System.out.println(ans);
    }
}
